{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "Cildo Meireles é artista conceitual brasileiro (faz obras em que a ideia importa mais que a técnica). Em 1978, durante a ditadura militar, ele criou uma cédula de valor zero, a Zero Cruzeiro. Ela imita uma nota oficial, mas mostra pessoas comuns e anônimas no lugar de heróis nacionais. A obra critica o dinheiro e a exclusão. Não é propaganda do governo.",
   "motivo": "Explica 'artista conceitual' e simplifica a frase final, sem mudar fatos."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["anverso e reverso", "os dois lados da nota: frente e verso"],
    ["valor nominal", "o valor escrito na nota; aqui, zero"],
    ["subverter", "inverter, virar de cabeça para baixo o sentido de algo estabelecido"],
    ["culto dos heróis", "hábito de exaltar figuras ilustres, como as que aparecem nas cédulas oficiais"],
    ["valor de troca", "a capacidade de uma coisa ser trocada por outra, como o dinheiro"],
    ["regime militar", "ditadura que governou o Brasil de 1964 a 1985"],
    ["anônimo", "pessoa cujo nome não é conhecido ou não aparece"],
    ["inflação", "alta geral dos preços, que faz o dinheiro comprar cada vez menos"],
    ["marginalizado", "pessoa ou grupo deixado à margem, sem acesso a direitos e reconhecimento"]
   ],
   "motivo": "Termos de A, B e E (inflação, marginalizados) e 'anônimo' aparecem na resolução e não estavam explicados."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "valor: \"0\" (zero)\nno lugar do herói: pessoas comuns",
   "motivo": "A conta anterior misturava aspas e itens soltos; agora cada linha diz o que olhar."
  },
  {
   "campo": "resolucao.passos[2].porque",
   "depois": "Na imagem, a assinatura é a do próprio artista. Não é a do presidente do Banco Central. Isso elimina a alternativa A.",
   "motivo": "Frases mais curtas e diretas."
  },
  {
   "campo": "resolucao.passos[4].porque",
   "depois": "O valor zero ironiza o dinheiro; não elogia a economia. Nada na obra mostra inclusão social feita pelo regime. Em 1978 havia censura, e a obra era crítica.",
   "motivo": "Frases curtas, sem duplo sentido."
  },
  {
   "campo": "resolucao.erradas.B",
   "depois": "Faltou ler o valor: zero ironiza o dinheiro. Nada na nota indica estabilização econômica ou queda da inflação. Essa leitura elogia o governo, o contrário da crítica da obra.",
   "motivo": "Diz o que faltou no raciocínio de quem marcou B; remove o termo 'anacrônica', que não se aplica."
  },
  {
   "campo": "resolucao.erradas.D",
   "depois": "Faltou notar que o valor zero tira da nota o valor de troca: com ela não se compra nada. A obra usa a forma da cédula para questionar o dinheiro, não para igualar arte e dinheiro.",
   "motivo": "Explicita o que faltou no raciocínio."
  },
  {
   "campo": "resolucao.erradas.E",
   "depois": "Faltou separar 'mostrar pessoas desvalorizadas' de 'elogiar o regime'. A obra dá visibilidade a anônimos como crítica, numa ditadura com censura. Não exalta política de inclusão do regime.",
   "motivo": "Mostra o ponto de confusão de quem marcou E."
  }
 ],
